pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);
        vm.prank(address(this));
        c.sudicideAnyone();
        assertTrue(address(c).balance == 0);
    }
}
